import pandas as pd, numpy as np
pd.set_option("display.width", 280); pd.set_option("display.max_columns", 80); pd.set_option("display.max_rows", 300)
df = pd.read_csv("out/returns.csv")
print(df.columns.tolist())
sc = df[df.status == "scored"].copy(); sc["is_candidate"] = sc.is_candidate.astype(bool); sc["same_plugin"] = sc.same_plugin.astype(bool)
print(pd.crosstab(sc.out_plugin, sc.out_mutual))
print(pd.crosstab(sc.out_split, sc.out_plugin))
print(pd.crosstab(sc.ceiling_class, sc.out_mutual))
print(pd.crosstab(sc.ceiling_class, sc.out_plugin))
print(sc.same_piece.value_counts(), sc.same_plugin.value_counts())
print("mutual status x outcome"); print(pd.crosstab(sc.mutual_status, sc.out_mutual))
print("not cand why"); print(sc[~sc.is_candidate].not_candidate_why.value_counts())
print("gap_s dist"); print(sc.gap_s.describe()); print((sc.gap_s > 10).sum(), (sc.piece_gap_s > 10).sum())
print("per clip"); print(df.groupby("clip").agg(n=("ret","size"), scored=("status", lambda s: (s=="scored").sum()), plugin_right=("out_plugin", lambda s:(s=="right").sum()), plugin_wrong=("out_plugin", lambda s:(s=="wrong").sum()), mutual_right=("out_mutual", lambda s:(s=="right").sum()), mutual_wrong=("out_mutual", lambda s:(s=="wrong").sum()), O1=("out_O1_links_known", lambda s:(s=="right").sum()), O2=("out_O2_links_any", lambda s:(s=="right").sum()), O4=("out_O4_cuts_links_any", lambda s:(s=="right").sum())))
cols = ["clip","ret","ref_id","gap_s","exit_side","reentry_side","piece_a","piece_b","a_rows","b_rows","a_matched","b_matched","a_ident","b_ident","a_ident_n","b_ident_n","a_purity","b_purity","b_prior_matched","b_prior_other_rows","out_split","out_plugin","out_mutual","out_O1_links_known","out_O2_links_any","out_O3_cuts_links_known","out_O4_cuts_links_any"]
print("--- not recoverable / cut class"); print(sc[sc.ceiling_class.isin(["not recoverable by cuts + links","needs an in-track switch fix (cut)"])][cols].to_string())
print("--- wrong under O1"); print(sc[sc.out_O1_links_known=="wrong"][cols].to_string())
print("--- wrong under O4"); print(sc[sc.out_O4_cuts_links_any=="wrong"][cols].to_string())
print("--- wrong under split"); print(sc[sc.out_split=="wrong"][cols].to_string())
